css:
.valuesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1b2733;
    background: linear-gradient(160deg, #eef1f4 0%, #e2e7ec 100%);
    border-radius: 18px;
}

.valuesim-container * {
    box-sizing: border-box;
}

.valuesim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #1f2a37 0%, #2c3e50 55%, #34556e 100%);
    color: #f4f7fa;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(31, 42, 55, 0.32);
    border-bottom: 4px solid #e8a33d;
}

.valuesim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.valuesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f3c987;
    background: rgba(232, 163, 61, 0.16);
    padding: 5px 14px;
    border-radius: 999px;
}

.valuesim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d7e0e8;
}

.valuesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2c3e50;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.valuesim-period-counter #currentDay,
.valuesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #1f2a37;
}

.valuesim-round-name {
    background: #d6dde4;
    color: #1f2a37;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.valuesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #a8521b;
    background: #fbe9d6;
    padding: 4px 12px;
    border-radius: 999px;
}

.valuesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.valuesim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d4dce4;
    box-shadow: 0 4px 14px rgba(31, 42, 55, 0.06);
    border-top: 4px solid #34556e;
}

.valuesim-card-capture { border-top-color: #1f8a70; }
.valuesim-card-cph { border-top-color: #2f6fb0; }
.valuesim-card-util { border-top-color: #7a5cc0; }
.valuesim-card-capital { border-top-color: #e8a33d; }

.valuesim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #62748a;
}

.valuesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1f2a37;
}

.valuesim-card-capture .valuesim-value { color: #1f8a70; }
.valuesim-card-cph .valuesim-value { color: #2f6fb0; }
.valuesim-card-util .valuesim-value { color: #7a5cc0; }
.valuesim-card-capital .valuesim-value { color: #b97c14; }

.valuesim-sublabel {
    font-size: 0.76rem;
    color: #76879a;
    line-height: 1.35;
}

.valuesim-capture-fail .valuesim-value { color: #c0392b; }
.valuesim-capture-target .valuesim-value { color: #1f8a70; }

.valuesim-util-low { border-top-color: #c0392b; }
.valuesim-util-low .valuesim-value { color: #c0392b; }

.valuesim-capital-over { border-top-color: #c0392b; }
.valuesim-capital-over .valuesim-value { color: #c0392b; }

.valuesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1f2a37;
    color: #eef3f7;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.valuesim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f3c987;
}

.valuesim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #e8a33d;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(31, 42, 55, 0.05);
}

.valuesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.valuesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1f2a37;
    margin-bottom: 6px;
}

.valuesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #34424f;
}

.valuesim-briefing-text strong { color: #1f8a70; }
.valuesim-briefing-text em { color: #a8521b; font-style: italic; }

.valuesim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d4dce4;
    box-shadow: 0 4px 14px rgba(31, 42, 55, 0.06);
}

.valuesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1f2a37;
    border-bottom: 2px solid #e6ebf0;
    padding-bottom: 8px;
}

.valuesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2a3a48;
    margin: 14px 0 6px;
}

.valuesim-container select,
.valuesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c2cdd7;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f7f9fb;
    color: #1b2733;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.valuesim-container select:focus,
.valuesim-container input[type="number"]:focus {
    outline: none;
    border-color: #2f6fb0;
    box-shadow: 0 0 0 3px rgba(47, 111, 176, 0.15);
}

.valuesim-container select option {
    background-color: #ffffff;
    color: #1b2733;
}

.valuesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #e8a33d;
}

.valuesim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2c5a7a;
    margin-top: 4px;
}

.valuesim-range-readout span:not(:first-child) {
    color: #1f8a70;
    font-weight: 800;
}

.valuesim-hint {
    font-size: 0.8rem;
    color: #76879a;
    margin-top: 4px;
    line-height: 1.4;
}

.valuesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.valuesim-container .btn-primary {
    background: linear-gradient(135deg, #1f8a70 0%, #2f6fb0 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(31, 138, 112, 0.28);
}

.valuesim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.valuesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c2cdd7;
    color: #62748a;
}

.valuesim-coach {
    background: #1f2a37;
    color: #eef3f7;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(31, 42, 55, 0.24);
    border-left: 5px solid #e8a33d;
}

.valuesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f3c987;
    margin-bottom: 8px;
}

.valuesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.valuesim-coach-body strong { color: #7fd9c2; }
.valuesim-coach-body em { color: #f3c987; font-style: italic; }

.valuesim-history,
.valuesim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d4dce4;
    box-shadow: 0 4px 14px rgba(31, 42, 55, 0.06);
}

.valuesim-history h3,
.valuesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1f2a37;
}

.valuesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2a3a48;
}

.valuesim-container table#usfHistoryTable th {
    background: #eaeff3;
    color: #1f2a37;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d4dce4;
}

.valuesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef2f5;
}

.valuesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8fafb;
}

.valuesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .valuesim-container {
        padding: 14px;
    }
    .valuesim-header h1 {
        font-size: 1.7rem;
    }
    .valuesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .valuesim-value {
        font-size: 2rem;
    }
    .valuesim-clock {
        margin-left: 0;
    }
    .valuesim-period-counter {
        font-size: 0.88rem;
    }
    .valuesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .valuesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion-message card (appended; dark-on-light, self-contained) */
.valuesim-cm { background:#f2f6f8; color:#14212b; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(0,0,0,0.18); }
.valuesim-cm-head { text-align:center; border-bottom:1px solid #d5e2e7; padding-bottom:14px; margin-bottom:16px; }
.valuesim-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#4c6470; font-weight:700; }
.valuesim-cm-scorewrap { margin:8px 0 2px; }
.valuesim-cm-score { font-size:52px; font-weight:800; color:#2f6fb0; line-height:1; }
.valuesim-cm-score-max { font-size:20px; color:#7f929a; font-weight:600; }
.valuesim-cm-grade { font-size:19px; font-weight:700; color:#14212b; margin-top:4px; }
.valuesim-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.valuesim-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.valuesim-cm-met { background:#cfe8e0; color:#1b6a58; }
.valuesim-cm-fail { background:#f5ddd7; color:#a3402e; }
.valuesim-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.valuesim-cm-metric { background:#e5eef1; border-radius:10px; padding:12px 16px; min-width:104px; text-align:center; }
.valuesim-cm-metric-val { font-size:22px; font-weight:800; color:#14212b; }
.valuesim-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#4c6470; margin-top:3px; }
.valuesim-cm-insights { background:#e5eef1; border-radius:10px; padding:14px 18px; }
.valuesim-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#4c6470; font-weight:700; margin-bottom:8px; }
.valuesim-cm-insights ul { margin:0; padding-left:18px; }
.valuesim-cm-insights li { font-size:14px; line-height:1.5; color:#26363c; margin-bottom:7px; }

