(function() {
    'use strict';

    class ValueAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Onde o Valor Vive`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ---- Numbers reference card (BRL) ----
            this.START_CAPTURE = 19;     // ~R$6 of R$31 created
            this.START_CPH = 9;          // R$/constraint-hour, blended starting blur
            this.START_UTIL = 86;        // % of 12M std hours
            this.CAPTURE_TARGET_LO = 35; // partner band
            this.CAPTURE_TARGET_HI = 45;
            this.CAPTURE_CAP = 50;       // hard ceiling — over-reach risks AGT walking
            this.CPH_CEILING = 24;       // hard clamp for per-hour contribution (visual/state headroom)
            this.CPH_TARGET = 20;        // composite normalization top — optimal play lands ~20, below the clamp
            this.UTIL_FLOOR = 60;        // stranded fixed cost
            this.UTIL_CEILING = 98;
            this.UTIL_GOOD = 92;         // composite normalization top for utilization
            this.CAPITAL_CAP = 40;       // R$40M board envelope
            this.RECONFIG_COST = 22;     // reconfiguration + metrology + training
            this.NEWLINE_COST = 35;      // relieve the ceiling
            this.BOTH_COST = 57;         // exceeds the cap

            this.COMPOSITE_TARGET = 68;  // credible board case
            this.COMPOSITE_EXEMPLARY = 82;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    capture: this.START_CAPTURE,
                    cph: this.START_CPH,
                    util: this.START_UTIL,
                    capitalUsed: 0,
                    quality: 28,        // hidden composite driver — starts low, big headroom
                    reconfigFunded: false, // reconfiguration capital committed (charged once)
                    capBust: false,
                    agtWalked: false,
                    captureHistory: [this.START_CAPTURE],
                    cphHistory: [this.START_CPH],
                    utilHistory: [this.START_UTIL],
                    qualityHistory: [28],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    lens: `perunit`,
                    gap: `module`,
                    rank: 0,
                    capability: `none`,
                    exit: `nothing`,
                    invest: 0,
                    share: 19,
                    tooling: `agt`,
                    volume: `none`,
                    plan: `nothing`,
                    finance: `defer`,
                    exit2: `none`,
                    pitch: 0
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const lens = document.getElementById(`lensInput`);
                const gap = document.getElementById(`gapInput`);
                const rank = document.getElementById(`rankInput`);
                if (lens) decisions.lens = lens.value;
                if (gap) decisions.gap = gap.value;
                if (rank) decisions.rank = parseInt(rank.value, 10);
                if (!Number.isFinite(decisions.rank) || decisions.rank < 0 || decisions.rank > 100) {
                    warn(`warn_rank_range`); return false;
                }
            } else if (round === 2) {
                const cap = document.getElementById(`capabilityInput`);
                const exit = document.getElementById(`exitInput`);
                const inv = document.getElementById(`investInput`);
                if (cap) decisions.capability = cap.value;
                if (exit) decisions.exit = exit.value;
                if (inv) decisions.invest = parseFloat(inv.value);
                if (!Number.isFinite(decisions.invest) || decisions.invest < 0 || decisions.invest > this.BOTH_COST) {
                    warn(`warn_invest_range`); return false;
                }
            } else if (round === 3) {
                const share = document.getElementById(`shareInput`);
                const tool = document.getElementById(`toolingInput`);
                const vol = document.getElementById(`volumeInput`);
                if (share) decisions.share = parseInt(share.value, 10);
                if (tool) decisions.tooling = tool.value;
                if (vol) decisions.volume = vol.value;
                if (!Number.isFinite(decisions.share) || decisions.share < 19 || decisions.share > 60) {
                    warn(`warn_share_range`); return false;
                }
            } else if (round === 4) {
                const plan = document.getElementById(`planInput`);
                const fin = document.getElementById(`financeInput`);
                const exit2 = document.getElementById(`exit2Input`);
                const pitch = document.getElementById(`pitchInput`);
                if (plan) decisions.plan = plan.value;
                if (fin) decisions.finance = fin.value;
                if (exit2) decisions.exit2 = exit2.value;
                if (pitch) decisions.pitch = parseInt(pitch.value, 10);
                if (!Number.isFinite(decisions.pitch) || decisions.pitch < 0 || decisions.pitch > 100) {
                    warn(`warn_pitch_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let captureDelta = 0, cphDelta = 0, utilDelta = 0, qualityDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // DIAGNOSE: contribution-per-constraint-hour is the lens; per-unit margin is the trap.
                switch (d.lens) {
                    case `perhour`:
                        cphDelta += 1.4; qualityDelta += 5; coachKey = `coach_r1_perhour`; break;
                    case `perunit`:
                        // Margin myopia — the module eats 1.9h/un, the bracket only 0.6h/un.
                        cphDelta -= 1.2; qualityDelta -= 8; coachKey = `coach_r1_perunit`; break;
                    case `revenue`:
                        cphDelta -= 0.8; qualityDelta -= 9; coachKey = `coach_r1_revenue`; break;
                    case `ebitda`:
                        cphDelta -= 0.4; qualityDelta -= 11; coachKey = `coach_r1_ebitda`; break;
                }

                // Locate the create-vs-capture gap: it lives in build-to-print (R$6 of R$31).
                switch (d.gap) {
                    case `buildtoprint`:
                        captureDelta += 1; qualityDelta += 4;
                        if (d.lens === `perhour`) coachKey = `coach_r1_sharp`;
                        break;
                    case `module`:
                        qualityDelta -= 6; coachKey = `coach_r1_gapmodule`; break;
                    case `none`:
                        qualityDelta -= 10; coachKey = `coach_r1_gapnone`; break;
                }

                // Ranking discipline by per-hour contribution before deciding.
                if (d.rank >= 80) { qualityDelta += 3; cphDelta += 0.6; }
                else if (d.rank >= 50) { qualityDelta += 1; }
                else { qualityDelta -= 5; coachKey = `coach_r1_lowrank`; }

                summaryKey = (d.lens === `perhour` && d.gap === `buildtoprint`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // PLAN: rebuild a scarce, defensible capability; free the worst per-hour hours; respect the cap.
                spend += d.invest;
                switch (d.capability) {
                    case `metrology`:
                        // Validated, scarce source — the most defensible claim on capture share.
                        captureDelta += 5; cphDelta += 1.6; qualityDelta += 6; coachKey = `coach_r2_metrology`; break;
                    case `coeng`:
                        // Real capability, slightly less defensible than being the validated source.
                        captureDelta += 3; cphDelta += 1.2; qualityDelta += 4; coachKey = `coach_r2_coeng`; break;
                    case `assembly`:
                        // Agility, low defensibility — easily replicated, weak capture claim.
                        captureDelta += 1; cphDelta += 0.4; qualityDelta += 1; coachKey = `coach_r2_assembly`; break;
                    case `none`:
                        // Capture without capability — nothing earns the share.
                        captureDelta -= 2; qualityDelta -= 12; coachKey = `coach_r2_capnone`; break;
                }

                switch (d.exit) {
                    case `commodity`:
                        // Drop the worst per-hour line (R$7.4/h) to free the constraint — correct.
                        cphDelta += 2.2; utilDelta += 1.5; qualityDelta += 4; coachKey = (d.capability === `metrology`) ? `coach_r2_planned` : coachKey; break;
                    case `agri`:
                        // Wrong displacement — agri runs R$13/h, your best per-hour business.
                        cphDelta -= 2.6; utilDelta -= 1.5; qualityDelta -= 9; coachKey = `coach_r2_exitagri`; break;
                    case `nothing`:
                        // Capacity binds — trying to fit everything strands the module ramp.
                        cphDelta -= 0.8; utilDelta -= 3; qualityDelta -= 6; coachKey = `coach_r2_exitnothing`; break;
                }

                // Investment discipline. R$22M reconfiguration funds the capability and fits the cap;
                // busting the R$40M envelope this early is punished and flagged.
                if (d.invest > this.CAPITAL_CAP) {
                    ds.capBust = true; qualityDelta -= 12; coachKey = `coach_r2_capbust`;
                } else if (d.invest >= this.RECONFIG_COST - 3 && d.invest <= this.CAPITAL_CAP) {
                    ds.reconfigFunded = true; captureDelta += 2; qualityDelta += 4;
                } else if (d.invest < 10) {
                    // Underfunding the reconfiguration starves the capability you just chose.
                    captureDelta -= 2; qualityDelta -= 5; coachKey = (d.capability !== `none`) ? `coach_r2_underfund` : coachKey;
                } else {
                    // Partial funding — capability lands but weakly.
                    ds.reconfigFunded = true; qualityDelta += 1;
                }

                summaryKey = (d.capability === `metrology` && d.exit === `commodity` && !ds.capBust) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // DECIDE: negotiate a value split anchored to capability, secure the volume, share tooling.
                // A scarce capability already built (metrology/coeng + funded reconfiguration) backs the claim.
                const backed = ds.quality >= 50;

                if (d.share >= this.CAPTURE_TARGET_LO && d.share <= this.CAPTURE_TARGET_HI) {
                    // In the achievable partner band.
                    if (backed) { captureDelta += 9; cphDelta += 1.4; qualityDelta += 6; coachKey = `coach_r3_band`; }
                    else { captureDelta += 3; qualityDelta -= 4; coachKey = `coach_r3_bandnobacking`; }
                } else if (d.share > this.CAPTURE_TARGET_HI) {
                    // Over-negotiating: AGT walks to Paraná, 40% volume gone, util collapses to ~64%.
                    ds.agtWalked = true;
                    captureDelta += 2; utilDelta -= 22; cphDelta -= 3; qualityDelta -= 14; coachKey = `coach_r3_overreach`;
                } else {
                    // Asking too little — leaves captured value on the table.
                    captureDelta += 2; qualityDelta -= 4; coachKey = `coach_r3_timid`;
                }

                switch (d.tooling) {
                    case `shared`:
                        // Relationship-specific investment on both sides — strongest claim.
                        captureDelta += 3; qualityDelta += 3; break;
                    case `agt`:
                        // AGT funds all — IMP risks no capital but weakens its claim.
                        captureDelta -= 3; qualityDelta -= 6; coachKey = `coach_r3_agtfunds`; break;
                    case `imp`:
                        // IMP funds all — takes all relationship-specific risk, strains the cap.
                        captureDelta -= 1; qualityDelta -= 4; coachKey = `coach_r3_impfunds`; break;
                }

                switch (d.volume) {
                    case `guaranteed`:
                        // Secures the multi-year volume that actually fills the constraint.
                        utilDelta += 4; cphDelta += 1; qualityDelta += 4; break;
                    case `exclusive`:
                        // Exclusivity without firm volume — capture share on a pie you can't fill.
                        utilDelta -= 4; qualityDelta -= 7; coachKey = `coach_r3_exclusive`; break;
                    case `none`:
                        // Spot pricing leaves the bottleneck unfilled.
                        utilDelta -= 6; qualityDelta -= 9; coachKey = `coach_r3_novolume`; break;
                }

                summaryKey = (!ds.agtWalked && d.share >= this.CAPTURE_TARGET_LO && d.share <= this.CAPTURE_TARGET_HI && d.volume === `guaranteed`) ? `sum_r3_good` : (ds.agtWalked ? `sum_r3_walked` : `sum_r3_weak`);
            } else if (round === 4) {
                // COMMIT: sequence interdependent investments under the cap; exit the right volume.
                // Reconfiguration is charged ONCE — if R2 already funded it, phasing adds no new capital;
                // if it was not yet funded, phasing commits it now (still inside the cap).
                switch (d.plan) {
                    case `phase`:
                        // Reconfigure for the value-capturing capability now; relieve the ceiling via lease (no capex).
                        if (!ds.reconfigFunded) { spend += this.RECONFIG_COST; ds.reconfigFunded = true; }
                        captureDelta += 2; cphDelta += 1; qualityDelta += 6; coachKey = `coach_r4_phase`; break;
                    case `both`:
                        // Commit the new line (R$35M) on top of the reconfiguration — R$57M total busts the R$40M cap.
                        spend += this.NEWLINE_COST;
                        if (!ds.reconfigFunded) { spend += this.RECONFIG_COST; ds.reconfigFunded = true; }
                        ds.capBust = true; qualityDelta -= 13; coachKey = `coach_r4_both`; break;
                    case `lineonly`:
                        // Capacity relief but none of the capability that captures value.
                        spend += this.NEWLINE_COST; captureDelta -= 4; cphDelta -= 1; qualityDelta -= 8; coachKey = `coach_r4_lineonly`; break;
                    case `nothing`:
                        // Pure build-to-print — accept the 4%/yr price-down and commoditization.
                        captureDelta -= 7; cphDelta -= 1.5; qualityDelta -= 14; coachKey = `coach_r4_nothing`; break;
                }

                switch (d.finance) {
                    case `lease`:
                        // Operating lease preserves the covenant and aligns cost to the ramp.
                        utilDelta += 4; qualityDelta += 3; break;
                    case `debt`:
                        // Full new debt with leverage already near covenant.
                        utilDelta += 1; qualityDelta -= 5; coachKey = (d.plan === `phase`) ? `coach_r4_debt` : coachKey; break;
                    case `defer`:
                        // Defer a year — bottleneck risk through the ramp.
                        utilDelta -= 4; qualityDelta -= 5; coachKey = (d.plan === `phase`) ? `coach_r4_defer` : coachKey; break;
                }

                switch (d.exit2) {
                    case `ranked`:
                        // Cut by per-hour ranking, keep the R$13/h agri — correct displacement.
                        cphDelta += 2.2; utilDelta += 1.5; qualityDelta += 4; break;
                    case `agri`:
                        // Exit agri — sacrificing the best per-hour business to free volume fast.
                        cphDelta -= 3; qualityDelta -= 9; coachKey = `coach_r4_exitagri`; break;
                    case `none`:
                        // No exit — the constraint never clears for the module ramp.
                        utilDelta -= 4; qualityDelta -= 6; coachKey = `coach_r4_exitnone`; break;
                }

                // Pitch: capture anchored to a real, scarce capability.
                if (d.pitch >= 75) { qualityDelta += 3; captureDelta += 1; }
                else if (d.pitch >= 50) { qualityDelta += 1; }
                else { qualityDelta -= 5; coachKey = `coach_r4_weakpitch`; }

                summaryKey = (d.plan === `phase` && d.finance === `lease` && d.exit2 === `ranked` && !ds.capBust) ? `sum_r4_good` : (ds.capBust ? `sum_r4_capbust` : `sum_r4_weak`);
            }

            // ---- Apply deltas with floors/caps that preserve headroom ----
            ds.capitalUsed = Math.round((ds.capitalUsed + spend) * 10) / 10;
            ds.capture = Math.max(0, Math.min(this.CAPTURE_CAP, Math.round((ds.capture + captureDelta) * 10) / 10));
            ds.cph = Math.max(0, Math.min(this.CPH_CEILING, Math.round((ds.cph + cphDelta) * 10) / 10));
            ds.util = Math.max(this.UTIL_FLOOR, Math.min(this.UTIL_CEILING, Math.round((ds.util + utilDelta) * 10) / 10));
            ds.quality = Math.max(0, Math.min(100, Math.round((ds.quality + qualityDelta) * 10) / 10));

            // Capital over the envelope drags the composite every remaining round.
            if (ds.capitalUsed > this.CAPITAL_CAP) ds.capBust = true;

            ds.captureHistory.push(Math.round(ds.capture));
            ds.cphHistory.push(Math.round(ds.cph * 10) / 10);
            ds.utilHistory.push(Math.round(ds.util));
            ds.qualityHistory.push(Math.round(ds.quality));

            const composite = this._composite(ds);
            // v1.1.0 fix: persist instructor-card composite to domainState every period.
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = composite;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                capture: Math.round(ds.capture),
                captureDelta: Math.round(captureDelta),
                cph: Math.round(ds.cph * 10) / 10,
                util: Math.round(ds.util),
                capitalUsed: ds.capitalUsed,
                composite: composite,
                capBust: ds.capBust,
                agtWalked: ds.agtWalked,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _composite(ds) {
            // Capture scored against the top of the partner band (45%); CPH against ceiling;
            // utilization against a "good" 92% target above a stranded-cost floor; quality is
            // the hidden process-correctness driver. Capital indiscipline and a broken
            // negotiation are explicit penalties so neither can be hidden by a high KPI.
            const captureScore = Math.max(0, Math.min(100, (ds.capture / this.CAPTURE_TARGET_HI) * 100));
            const cphScore = Math.max(0, Math.min(100, (ds.cph / this.CPH_TARGET) * 100));
            const utilScore = Math.max(0, Math.min(100, ((ds.util - this.UTIL_FLOOR) / (this.UTIL_GOOD - this.UTIL_FLOOR)) * 100));
            let composite = captureScore * 0.33 + cphScore * 0.25 + utilScore * 0.17 + ds.quality * 0.25;
            if (ds.capBust) composite -= 12;
            if (ds.agtWalked) composite -= 10;
            return Math.max(0, Math.round(composite));
        }

