        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.captureHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : window.mySimulation.t(`chart_round_prefix`) + i));
            return {
                valueChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.captureHistory },
                        { data: ds.cphHistory },
                        { data: ds.utilHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const capture = Math.round(ds.capture);
            const cph = Math.round(ds.cph * 10) / 10;
            const util = Math.round(ds.util);
            const composite = this._composite(ds);

            const inBand = capture >= this.CAPTURE_TARGET_LO && capture <= this.CAPTURE_CAP;
            const disciplined = !ds.capBust && ds.capitalUsed <= this.CAPITAL_CAP;
            const filled = util >= this.START_UTIL && !ds.agtWalked;

            let performanceKey = `grade_commodity`;
            if (composite >= this.COMPOSITE_EXEMPLARY && inBand && disciplined && filled) performanceKey = `grade_captured`;
            else if (composite >= this.COMPOSITE_TARGET && inBand && disciplined) performanceKey = `grade_credible`;
            else if (ds.agtWalked) performanceKey = `grade_walked`;
            else if (ds.capBust) performanceKey = `grade_capbust`;
            else if (composite >= 55) performanceKey = `grade_progress`;
            const met = composite >= this.COMPOSITE_EXEMPLARY && inBand && disciplined && filled;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (composite >= this.COMPOSITE_EXEMPLARY && inBand && disciplined && filled) insights.push(window.mySimulation.t(`insight_exemplary`));
            else if (composite >= this.COMPOSITE_TARGET && inBand && disciplined) insights.push(window.mySimulation.t(`insight_credible`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.agtWalked) insights.push(window.mySimulation.t(`insight_walked`));
            if (ds.capBust) insights.push(window.mySimulation.t(`insight_capbust`));
            if (!inBand && !ds.agtWalked) insights.push(window.mySimulation.t(`insight_capture`));
            if (cph < 12) insights.push(window.mySimulation.t(`insight_cph`));
            if (util < 70) insights.push(window.mySimulation.t(`insight_util`));

            return {
                capture: capture,
                cph: cph,
                util: util,
                capitalUsed: ds.capitalUsed,
                composite: composite,
                inBand: inBand,
                disciplined: disciplined,
                filled: filled,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                agtWalked: !!ds.agtWalked,
                capBust: !!ds.capBust,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k, v) => window.mySimulation.t(k, v);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="valuesim-cm-badge ` + (s.met ? `valuesim-cm-met` : `valuesim-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.agtWalked) badges.push(`<span class="valuesim-cm-badge valuesim-cm-fail">` + t(`cm_fail_walked`) + `</span>`);
            if (s.capBust) badges.push(`<span class="valuesim-cm-badge valuesim-cm-fail">` + t(`cm_fail_capbust`) + `</span>`);
            if (s.inBand === false) badges.push(`<span class="valuesim-cm-badge valuesim-cm-fail">` + t(`cm_fail_band`) + `</span>`);
            if (s.filled === false) badges.push(`<span class="valuesim-cm-badge valuesim-cm-fail">` + t(`cm_fail_util`) + `</span>`);
            const kpi = (label, val) => `<div class="valuesim-cm-metric"><div class="valuesim-cm-metric-val">` + val + `</div><div class="valuesim-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_capture`), (s.capture != null ? Math.round(s.capture) : 0) + `%`)
                + kpi(t(`cm_cph`), `R$` + (s.cph != null ? s.cph : 0))
                + kpi(t(`cm_util`), (s.util != null ? Math.round(s.util) : 0) + `%`)
                + kpi(t(`cm_capital`), `R$` + (s.capitalUsed != null ? s.capitalUsed : 0) + `M`);
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="valuesim-cm">`
                + `<div class="valuesim-cm-head"><div class="valuesim-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="valuesim-cm-scorewrap"><span class="valuesim-cm-score">` + score + `</span><span class="valuesim-cm-score-max">/100</span></div>`
                + `<div class="valuesim-cm-grade">` + grade + `</div>`
                + `<div class="valuesim-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="valuesim-cm-metrics">` + kpis + `</div>`
                + `<div class="valuesim-cm-insights"><div class="valuesim-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.agtWalked) return window.mySimulation.t(`hint_walked`);
            if (ds.capBust) return window.mySimulation.t(`hint_capbust`);
            if (state.currentPeriod >= 2 && ds.quality < 35) return window.mySimulation.t(`hint_capability`);
            if (state.currentPeriod >= 3 && ds.capture < this.CAPTURE_TARGET_LO) return window.mySimulation.t(`hint_capture`);
            if (ds.cph < 10 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_cph`);
            if (this._composite(ds) >= this.COMPOSITE_TARGET && state.currentPeriod >= 3) return window.mySimulation.t(`hint_strong`);
            return null;
        }

